import type { OverlayProps } from "./overlay.types";

import { Presence } from "@radix-ui/react-presence";
import { RemoveScroll } from "react-remove-scroll";
import { createSlot } from "@radix-ui/react-slot";
import { Primitive } from "@radix-ui/react-primitive";
import { forwardRef, useId } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import * as RadixDialog from "@radix-ui/react-dialog";
import { VisuallyHidden } from "@radix-ui/react-visually-hidden";
import { isNullish } from "@system";
import { usePortalContainer } from "@hooks/use-portal-container";

import { OverlayClasses, StyledContent, StyledOverlay } from "./overlay.styles";

const Overlay = forwardRef<HTMLDivElement, OverlayProps>(
  (
    {
      className,
      children,
      containerElement,
      variant = "default",
      open,
      defaultOpen = false,
      onOpenChange,
      dismissible = true,
      title = "Overlay",
      description,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(OverlayClasses.root, className);
    const { resolvedContainer, isScoped } = usePortalContainer(containerElement);
    const descriptionId = useId();

    return (
      <RadixDialog.Root
        defaultOpen={defaultOpen}
        modal={isNullish(containerElement)}
        open={open}
        onOpenChange={(open) => {
          onOpenChange?.(open);
        }}
      >
        <RadixDialog.Portal container={resolvedContainer}>
          <StyledOverlay
            as={RadixDialogOverlayOverride}
            className={rootClasses}
            containerElement={containerElement}
            currentTheme={theme}
            data-textura-scoped={isScoped}
            styleSlots={props.styleSlots}
            variant={variant}
          />
          <StyledContent
            ref={ref}
            aria-describedby={description ? descriptionId : undefined}
            className={OverlayClasses.content}
            currentTheme={theme}
            data-textura-scoped={isScoped}
            variant={variant}
            onEscapeKeyDown={(e) => {
              if (dismissible) return;
              e.preventDefault();
            }}
            onInteractOutside={(e) => {
              if (dismissible) return;
              e.preventDefault();
            }}
            onPointerDownOutside={(e) => {
              if (dismissible) return;
              e.preventDefault();
            }}
            {...props}
          >
            <VisuallyHidden>
              <RadixDialog.Title>{title}</RadixDialog.Title>
              {description && (
                <RadixDialog.Description id={descriptionId}>{description}</RadixDialog.Description>
              )}
            </VisuallyHidden>
            {children}
          </StyledContent>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    );
  },
);
Overlay.displayName = "Overlay";

const Slot = createSlot("DialogOverlay.RemoveScroll");
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const RadixDialogOverlayOverride = forwardRef<HTMLDivElement, any>(
  ({ containerElement, ...props }, ref) => {
    return (
      <Presence present={true}>
        <RemoveScroll allowPinchZoom as={Slot} enabled={isNullish(containerElement)}>
          <Primitive.div {...props} ref={ref} style={{ pointerEvents: "auto", ...props.style }} />
        </RemoveScroll>
      </Presence>
    );
  },
);
RadixDialogOverlayOverride.displayName = "RadixDialogOverlayOverride";

export default Overlay;
